await tool.tabs_close({ tabId: 787783904 });

const candidates = [
  "Sangnok Art Hall",
  "Novotel Ambassador Seoul Gangnam",
  "Josun Palace Seoul Gangnam",
  "Park Hyatt Seoul wedding",
  "Gramercy COEX wedding",
  "Celeb and Assem wedding"
];

const tabId = 787783793;
// Let's search DuckDuckGo for official sites of these venues
const results = {};
for (const c of candidates) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(c + " official site")}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 }).catch(() => {});
  const links = await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll("a")).map(a => a.href).filter(h => h && h.startsWith("http") && !h.includes("duckduckgo.com")).slice(0, 3);
  });
